sql_query:
SELECT SUM(order_subtotal) as total_subtotal
FROM common_order
WHERE order_channel = 'Swiggy';

SELECT SUM(order_subtotal) as Total_Subtotal
FROM common_order
WHERE order_channel = 'website';

SELECT SUM(order_subtotal) as Total_Subtotal
FROM common_order
WHERE order_channel LIKE '%phone%';

SELECT SUM(order_subtotal) as Total_Subtotal
FROM common_order
WHERE order_channel IS NOT NULL;

SELECT COUNT(order_id) AS total_orders
FROM common_order
WHERE order_channel = 'Zomato';

SELECT COUNT(*)
FROM common_order
WHERE order_channel IN ('Zomato', 'Swiggy');

SELECT SUM(CASE WHEN order_channel = 'Zomato' THEN 1 ELSE 0 END) AS zomato_orders,
       SUM(CASE WHEN order_channel = 'Swiggy' THEN 1 ELSE 0 END) AS swiggy_orders
FROM common_order;

SELECT SUM(order_total) as total_revenue
FROM common_order
WHERE order_channel = 'Swiggy';

SELECT SUM(order_total) as total_orders
FROM common_order
WHERE biz_name = 'cheesiano pizza' AND fulfillment_mode = 'delivery';
